<script lang="ts" setup>
function moduleImage(icon: string = '') {
  if (!icon) return

  if (/^https?:\/\//.test(icon)) return icon

  return `https://raw.githubusercontent.com/nuxt/modules/main/icons/${icon}`
}

defineProps<{
  icon?: string
  headline?: string
  title: string
  description?: string
}>()
